SELECT COUNT(DISTINCT d.district_id) AS count
FROM district d
WHERE CAST(d.a11 AS INTEGER) > 6000 AND CAST(d.a11 AS INTEGER) < 10000;

SELECT COUNT(*) as post_count
FROM posts
WHERE ownerdisplayname = 'Tiago Pasqualini';

SELECT DISTINCT d.nationality
FROM drivers d
WHERE d.dob = (SELECT MIN(dob) FROM drivers WHERE dob IS NOT NULL);
